 "content": "def transform(grid):
    """Draw 3s along row/column runs bounded by two non-background marks."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v != bg]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != bg]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
    return out
